<?php
require_once __DIR__.'/../config/security.php'; require_permission('tickets.manage');
$method=$_SERVER['REQUEST_METHOD']; $data=json_decode(file_get_contents('php://input'),true)?:$_POST;
if($method==='POST'){ $title=trim($data['title']??'');$desc=trim($data['description']??'');if(!$title||!$desc)json_response(['ok'=>false,'message'=>'Title and description are required.'],422);$no='INC-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(2)));$pdo->prepare('INSERT INTO tickets(ticket_no,title,description,priority,status,category,reporter_id,technician_id,room) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$no,$title,$desc,$data['priority']??'Medium','Open',$data['category']??'Network',$_SESSION['user_id']??null,$data['technician_id']?:null,$data['room']??null]);audit('Created ticket',$no);json_response(['ok'=>true,'ticket_no'=>$no]);}
if($method==='PATCH'){ $id=(int)($data['id']??0);$status=$data['status']??'In Progress';$resolution=$data['resolution']??null;$tech=$data['technician_id']??null;$resolved=in_array($status,['Resolved','Closed'],true)?date('Y-m-d H:i:s'):null;$pdo->prepare('UPDATE tickets SET status=?,resolution=?,technician_id=?,resolved_at=? WHERE id=?')->execute([$status,$resolution,$tech?:null,$resolved,$id]);audit('Updated ticket','#'.$id.' '.$status);json_response(['ok'=>true]);}
json_response(['ok'=>false,'message'=>'Unsupported request'],405);
